140	// existing checkpoint — attach, which adds a session to it — but attach
141	// pre-fetches and verifies the ref's presence itself (refreshCheckpoint)
142	// before writing, so the local-only probe is safe there too.
143	func (s *gitRefsStore) refBase(cid id.CheckpointID) (plumbing.Hash, *object.Tree, error) {
144		refName, err := RefName(cid)
145		if err != nil {
146			return plumbing.ZeroHash, nil, err
147		}
148		ref, err := s.repo.Reference(refName, true)
149		if errors.Is(err, plumbing.ErrReferenceNotFound) {
150			return plumbing.ZeroHash, nil, nil // no ref yet → new checkpoint (orphan)
151		}
152		if err != nil {
153			// A real lookup failure (IO/corruption), not an absent ref: surface it
154			// rather than silently starting a fresh orphan history over the ref.
155			return plumbing.ZeroHash, nil, fmt.Errorf("resolve checkpoint ref %s: %w", refName, err)
156		}
157		return s.refTip(cid, ref)
158	}
159	
160	// refBaseForBackfill resolves like refBase, but a ref missing locally is
161	// first fetched once from the remote (resolveRefMaybeFetch) when a fetcher is
162	// configured: a backfill targets an EXISTING checkpoint that may have been
163	// written or migrated on another machine, and declaring it absent without
164	// looking remotely diverges from the read path — the backfill would be
165	// handled as targeting a nonexistent checkpoint while reads, which DO fetch,
166	// serve the refs copy, leaving the backfilled data permanently invisible.
167	// A ref absent even after the fetch yields (ZeroHash, nil), which the
168	// backfill helpers report as ErrCheckpointNotFound — the signal that the
169	// checkpoint does not exist in this backend. A fetch FAILURE is returned
170	// as-is: transient unavailability must never masquerade as absence, because
171	// a caller or routing layer acting on a false "absent" would misdirect the
172	// backfill (e.g. onto a stale copy in another backend) instead of retrying.
173	func (s *gitRefsStore) refBaseForBackfill(ctx context.Context, cid id.CheckpointID) (plumbing.Hash, *object.Tree, error) {
174		ref, err := s.resolveRefMaybeFetch(ctx, cid)
175		if errors.Is(err, plumbing.ErrReferenceNotFound) {
176			return plumbing.ZeroHash, nil, nil // genuinely absent → backfill reports not-found
177		}
178		if err != nil {
179			return plumbing.ZeroHash, nil, err
180		}
181		return s.refTip(cid, ref)
182	}
183	
184	// refTip reads the commit and tree at a resolved checkpoint ref.
185	func (s *gitRefsStore) refTip(cid id.CheckpointID, ref *plumbing.Reference) (plumbing.Hash, *object.Tree, error) {
186		commit, err := s.repo.CommitObject(ref.Hash())
187		if err != nil {
188			return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint commit %s: %w", ref.Hash(), err)
189		}
190		tree, err := commit.Tree()
191		if err != nil {
192			return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint tree for %s: %w", cid, err)
193		}
194		return ref.Hash(), tree, nil
195	}
196	
197	// setRef points a checkpoint's ref at a new commit and records it for push.
198	// Enqueue is best-effort: a write that lands locally but fails to enqueue must
199	// not fail condensation. The ref is still local; only its remote sync is missed
200	// until a later write to the same checkpoint re-enqueues it.
201	func (s *gitRefsStore) setRef(ctx context.Context, cid id.CheckpointID, hash plumbing.Hash) error {
202		refName, err := RefName(cid)
203		if err != nil {
204			return err
205		}
206		if err := s.repo.Storer.SetReference(plumbing.NewHashReference(refName, hash)); err != nil {
207			return fmt.Errorf("set checkpoint ref %s to %s: %w", refName, hash, err)
208		}
209		s.enqueueForPush(ctx, refName)
210		return nil
211	}
212	
213	// enqueueForPush records refName in the push-discovery queue, logging (never
214	// returning) on failure so the local ref write still succeeds.
215	func (s *gitRefsStore) enqueueForPush(ctx context.Context, refName plumbing.ReferenceName) {
216		q, err := PushQueueForRepo(ctx, s.repo)
217		if err != nil {
218			logging.Warn(ctx, "checkpoint: resolve push queue failed; ref not enqueued",
219				slog.String("ref", refName.String()), slog.String("error", err.Error()))
220			return
221		}
222		if err := q.Enqueue(refName); err != nil {
223			logging.Warn(ctx, "checkpoint: enqueue checkpoint ref for push failed",
224				slog.String("ref", refName.String()), slog.String("error", err.Error()))
225		}
226	}
227	
228	func (s *gitRefsStore) writeSession(ctx context.Context, opts WriteOptions) error {
229		if opts.CheckpointID.IsEmpty() {
230			return errors.New("invalid checkpoint options: checkpoint ID is required")
231		}
232		if err := validation.ValidateSessionID(opts.SessionID); err != nil {
233			return fmt.Errorf("invalid checkpoint options: %w", err)
234		}
235		if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
236			return fmt.Errorf("invalid checkpoint options: %w", err)
237		}
238		if err := validation.ValidateAgentID(opts.AgentID); err != nil {
239			return fmt.Errorf("invalid checkpoint options: %w", err)
240		}
241	
242		parentHash, existing, err := s.refBase(opts.CheckpointID)
243		if err != nil {
244			return err
245		}
246	
247		checkpointSubtree, taskMetadataPath, err := s.applySessionWrite(ctx, opts, existing, "")
248		if err != nil {
249			return err
250		}
251	
252		commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
253		commitHash, err := CreateCommit(ctx, s.repo, checkpointSubtree, parentHash, commitMsg, opts.AuthorName, opts.AuthorEmail)
254		if err != nil {
255			return err
256		}
257		return s.setRef(ctx, opts.CheckpointID, commitHash)
258	}
