14	func resolveGitCommonDir(ctx context.Context, repo *git.Repository) (string, error) {
15		worktree, err := repo.Worktree()
16		if err != nil {
17			return "", fmt.Errorf("open worktree for git common dir: %w", err)
18		}
19		root := worktree.Filesystem().Root()
20		if root == "" {
21			return "", errors.New("resolve worktree root for git common dir")
22		}
23	
24		cmd := exec.CommandContext(ctx, "git", "-C", root, "rev-parse", "--git-common-dir")
25		// Use Output (not CombinedOutput) so stderr never pollutes the resolved
26		// path on success. Output populates ExitError.Stderr when cmd.Stderr is
27		// nil, so error detail is still available without merging streams.
28		output, err := cmd.Output()
29		if err != nil {
30			var exitErr *exec.ExitError
31			if errors.As(err, &exitErr) {
32				if detail := strings.TrimSpace(string(exitErr.Stderr)); detail != "" {
33					return "", fmt.Errorf("resolve git common dir: %w: %s", err, detail)
34				}
35			}
36			return "", fmt.Errorf("resolve git common dir: %w", err)
37		}
38		commonDir := strings.TrimSpace(string(output))
39		if commonDir == "" {
40			return "", errors.New("resolve git common dir: empty output")
41		}
42		if !filepath.IsAbs(commonDir) {
43			commonDir = filepath.Join(root, commonDir)
44		}
45		return filepath.Clean(commonDir), nil
46	}
