func (p *Progress) sessionStart(sessionIndex, sessionTotal int, agentName, sessionID string, turnCount int) {
	if p == nil || p.SessionStart == nil {
		return
	}
	p.SessionStart(sessionIndex, sessionTotal, agentName, sessionID, turnCount)
